mapper.select:
SELECT s.store_id,s.merchant_id,s.name,s.status,s.version FROM store_record s WHERE s.tenant_id=#{tenant} AND s.status='ACTIVE' AND s.store_id>#{after}
AND EXISTS(SELECT 1 FROM store_operator_grant g WHERE g.tenant_id=s.tenant_id AND g.actor_id=#{actor} AND g.active=TRUE AND g.permission='CATALOG' AND ((g.resource_type='STORE' AND g.resource_id=s.store_id) OR (g.resource_type='MERCHANT' AND g.resource_id=s.merchant_id)))
ORDER BY s.store_id LIMIT #{limit}
